SELECT COUNT(*) slots,SUM(e.saved_at<>v.a) birth_timestamp_mismatch,SUM(er.saved_at<>fr.a) reference_timestamp_mismatch,SUM(e.rev_id IS NULL) missing_birth_edit,SUM(fr.a IS NOT NULL AND er.rev_id IS NULL) missing_reference_edit FROM first_versions v JOIN current n USING(page_id,slot) LEFT JOIN wtt.edit e ON e.rev_id=v.born_rev LEFT JOIN first_refs fr ON fr.page_id=v.page_id AND fr.slot=v.slot LEFT JOIN wtt.edit er ON er.rev_id=fr.born_rev;
